-- Save MJ: Template Contents (core SP call only)
DO $mj$
DECLARE
  p_ID_61a58361 UUID;
  p_TemplateID_61a58361 UUID;
  p_TypeID_61a58361 UUID;
  p_TemplateText_61a58361 TEXT;
  p_Priority_61a58361 INTEGER;
  p_IsActive_61a58361 BOOLEAN;
BEGIN
  p_ID_61a58361 := 'b0361890-c7e5-49c3-98e0-310e2e74e514';
  p_TemplateID_61a58361 := '63E708A9-C0AE-4F67-913D-0CA23CF43609';
  p_TypeID_61a58361 := 'E7AFCCEC-6A37-EF11-86D4-000D3A4E707E';
  p_TemplateText_61a58361 := 'You are a focused summarization specialist. An AI agent needs a slice of stored conversation history summarized through a specific lens — it cannot afford to load the raw messages into its context, so your summary is what it will work from.

# Lens

Summarize ONLY what is relevant to this focus:

```
{{ lens }}
```

# Messages

Each line is prefixed with its permanent sequence number (`[seq N]`) — these are stable, addressable handles the agent can use to fetch exact messages later:

```
{{ messages }}
```

# Task

Produce a tight, lens-focused summary of these messages:

- Lead with the direct answer to the lens if one exists in the messages.
- Reference specific messages by their sequence numbers (`seq 42`) for every substantive claim, so the agent can page in the exact wording when it matters.
- Preserve exact identifiers, names, quantities, and quoted phrases verbatim — never paraphrase them.
- Note explicitly if the messages do NOT contain information the lens asks about. Never invent or infer beyond what is written.
- Ignore content irrelevant to the lens entirely; brevity is the point.

# Output

Return ONLY the summary text (markdown, no code fences, no preamble).
';
  p_Priority_61a58361 := 1;
  p_IsActive_61a58361 := TRUE;
  PERFORM __mj."spCreateTemplateContent"(p_ID := p_ID_61a58361, p_TemplateID := p_TemplateID_61a58361, p_TypeID := p_TypeID_61a58361, p_TemplateText := p_TemplateText_61a58361, p_Priority := p_Priority_61a58361, p_IsActive := p_IsActive_61a58361);
END $mj$;

