DO $mj$
DECLARE
  p_Name_3f1b1b35 VARCHAR(255);
  p_CategoryID_3f1b1b35 UUID;
  p_UserQuestion_3f1b1b35 TEXT;
  p_Description_3f1b1b35 TEXT;
  p_SQL_3f1b1b35 TEXT;
  p_TechnicalDescription_3f1b1b35 TEXT;
  p_OriginalSQL_3f1b1b35 TEXT;
  p_Feedback_3f1b1b35 TEXT;
  p_Status_3f1b1b35 VARCHAR(15);
  p_QualityRank_3f1b1b35 INTEGER;
  p_ExecutionCostRank_3f1b1b35 INTEGER;
  p_UsesTemplate_3f1b1b35 BOOLEAN;
  p_AuditQueryRuns_3f1b1b35 BOOLEAN;
  p_CacheEnabled_3f1b1b35 BOOLEAN;
  p_CacheTTLMinutes_3f1b1b35 INTEGER;
  p_CacheMaxSize_3f1b1b35 INTEGER;
  p_EmbeddingVector_3f1b1b35 TEXT;
  p_EmbeddingModelID_3f1b1b35 UUID;
  p_CacheValidationSQL_3f1b1b35 TEXT;
  p_SQLDialectID_3f1b1b35 UUID;
  p_Reusable_3f1b1b35 BOOLEAN;
  p_ExternalDataSourceID_3f1b1b35 UUID;
  p_ID_3f1b1b35 UUID;
BEGIN
  p_Name_3f1b1b35 := 'GetConversationsForMemoryManager';
  p_CategoryID_3f1b1b35 := '5609FBC7-381C-4F9C-9C74-04B52C1FF3DA';
  p_UserQuestion_3f1b1b35 := 'What conversations have new activity that need to be analyzed for memory extraction?';
  p_Description_3f1b1b35 := 'Returns all conversation data needed for memory extraction in a single query: conversations with new activity, their details with ratings, and linked agent runs for scope inheritance. Optimized to replace 4 separate sequential queries.';
  p_SQL_3f1b1b35 := '-- Get Conversations for Memory Manager - Single optimized query
-- Returns all data needed for memory extraction: conversations, details, ratings, and agent runs
-- Uses JSON aggregation to include related data without row multiplication
-- This replaces 4 separate queries with 1 query for better performance
--
-- Parameters:
--   @since (optional): ISO date string - only include conversations with new activity after this date
--   @agentIds: Array of agent IDs that have memory enabled (rendered via sqlIn filter)

SELECT
    c.ID as ConversationID,
    c.UserID,

    -- Most recent agent run ID for this conversation (for scope inheritance)
    (
        SELECT TOP 1 ar.ID
        FROM [__mj].[vwAIAgentRuns] ar
        WHERE ar.ConversationID = c.ID
        AND ar.AgentID IN {{ agentIds | sqlIn }}
        ORDER BY ar.StartedAt DESC
    ) as AgentRunID,

    -- Conversation details as JSON array with ratings included
    (
        SELECT
            cd.ID as id,
            cd.Role as role,
            cd.Message as message,
            cd.__mj_CreatedAt as createdAt,
            cdr.Rating as rating,
            cdr.Comments as ratingComment
        FROM [__mj].[vwConversationDetails] cd
        LEFT OUTER JOIN [__mj].[vwConversationDetailRatings] cdr
            ON cdr.ConversationDetailID = cd.ID
        WHERE cd.ConversationID = c.ID
        AND cd.Status = ''Complete''
        ORDER BY cd.__mj_CreatedAt ASC
        FOR JSON PATH
    ) as MessagesJSON,

    -- Rating summary flags
    CASE WHEN EXISTS (
        SELECT 1 FROM [__mj].[vwConversationDetails] cd
        INNER JOIN [__mj].[vwConversationDetailRatings] cdr ON cdr.ConversationDetailID = cd.ID
        WHERE cd.ConversationID = c.ID AND cdr.Rating >= 8
    ) THEN 1 ELSE 0
END as HasPositiveRating,

    CASE WHEN EXISTS (
        SELECT 1 FROM [__mj].[vwConversationDetails] cd
        INNER JOIN [__mj].[vwConversationDetailRatings] cdr ON cdr.ConversationDetailID = cd.ID
        WHERE cd.ConversationID = c.ID AND cdr.Rating <= 3
    ) THEN 1 ELSE 0
END as HasNegativeRating,

    CASE WHEN NOT EXISTS (
        SELECT 1 FROM [__mj].[vwConversationDetails] cd
        INNER JOIN [__mj].[vwConversationDetailRatings] cdr ON cdr.ConversationDetailID = cd.ID
        WHERE cd.ConversationID = c.ID
    ) THEN 1 ELSE 0
END as IsUnrated

FROM [__mj].[vwConversations] c

-- Only include conversations with new activity since last run
WHERE EXISTS (
    SELECT 1 FROM [__mj].[vwConversationDetails] cd_new
    WHERE cd_new.ConversationID = c.ID
    {% if since %}
    AND cd_new.__mj_CreatedAt >= {{ since | sqlDate }}
    {% endif %}
)

-- Only include conversations linked to agents that have memory enabled
AND EXISTS (
    SELECT 1 FROM [__mj].[vwAIAgentRuns] ar
    WHERE ar.ConversationID = c.ID
    AND ar.AgentID IN {{ agentIds | sqlIn }}
)

ORDER BY c.__mj_UpdatedAt DESC
';
  p_TechnicalDescription_3f1b1b35 := 'Single-query optimization that replaces 4 separate RunView calls in Memory Manager (get conversations, get agent runs, get details, get ratings). Uses SQL Server FOR JSON PATH to aggregate conversation details with ratings as JSON arrays. Returns rating summary flags (HasPositiveRating, HasNegativeRating, IsUnrated) and most recent AgentRunID for scope inheritance. Reduces database round trips from 4 to 1.';
  p_Status_3f1b1b35 := 'Approved';
  p_QualityRank_3f1b1b35 := 9;
  p_ExecutionCostRank_3f1b1b35 := 3;
  p_UsesTemplate_3f1b1b35 := TRUE;
  p_AuditQueryRuns_3f1b1b35 := FALSE;
